# Workflow steps at which the award exists but nothing is provisioned yet: the
# decision is being drafted, or has been taken and awaits the applicant.
OPEN_ALLOCATION_STEPS = ("allocation_decision", "award_response")


def prefill_open_allocations(apps, schema_editor):
    """Give every open allocation the award it would have got on activation.

    The plan is left empty, as on activation: the item follows the call
    offering's plan until the call manager picks another.

    Proposals at the allocation decision (or past it, awaiting the award
    response) and not yet provisioned get their request copied into an award,
    as activating the step now does. Provisioned proposals are left alone:
    their resources are the record of what was granted. Every other proposal is
    prefilled when its allocation decision starts, or at allocation at the
    latest, so none is provisioned without one.
    """
    Proposal = apps.get_model("proposal", "Proposal")
    RequestedResource = apps.get_model("proposal", "RequestedResource")
    AwardedResource = apps.get_model("proposal", "AwardedResource")

    now = timezone.now()
    proposals = Proposal.objects.filter(
        workflow_step__in=OPEN_ALLOCATION_STEPS,
        project__isnull=True,
        awarded_resources_prefilled_at__isnull=True,
    )
    for proposal in proposals.iterator():
        requested_resources = (
            RequestedResource.objects.filter(proposal=proposal)
            .select_related("requested_offering")
            .order_by("created", "id")
        )
        AwardedResource.objects.bulk_create(
            [
                AwardedResource(
                    proposal=proposal,
                    requested_resource=requested,
                    requested_offering=requested.requested_offering,
                    attributes=requested.attributes,
                    limits=requested.limits,
                    description=requested.description,
                )
                for requested in requested_resources
            ]
        )
        Proposal.objects.filter(pk=proposal.pk).update(
            awarded_resources_prefilled_at=now
        )


